"use strict";

const fs = require("fs");
const path = require("path");

const projectRoot = path.resolve(__dirname, "..");
const srcRoot = path.join(projectRoot, "src");
const outputDir = path.join(srcRoot, "renderer-bundles");
const entryPoints = [
  "app",
  "customer-ledger",
  "supplier-ledger",
  "cashboxes",
  "reconciliation-requests-manager"
].map((name) => ({ name, input: path.join(srcRoot, `${name}.js`) }));

const externalModules = { dexie: { globalName: "Dexie" } };

function normalizePath(filePath) {
  return path.relative(projectRoot, filePath).replace(/\\/g, "/");
}

function resolveLocalModule(parentFile, request) {
  const basePath = path.resolve(path.dirname(parentFile), request);
  const candidates = [basePath, `${basePath}.js`, path.join(basePath, "index.js")];
  const resolved = candidates.find((candidate) => fs.existsSync(candidate) && fs.statSync(candidate).isFile());
  if (!resolved) throw new Error(`Cannot resolve ${request} from ${normalizePath(parentFile)}`);
  return path.resolve(resolved);
}

function collectModuleGraph(entryFile) {
  const moduleMap = new Map();
  function visit(filePath) {
    const absolutePath = path.resolve(filePath);
    if (moduleMap.has(absolutePath)) return;
    const source = fs.readFileSync(absolutePath, "utf8").replace(/\r\n/g, "\n");
    const dependencyMap = {};
    const requirePattern = /require\s*\(\s*['"]([^'"]+)['"]\s*\)/g;
    for (const match of source.matchAll(requirePattern)) {
      const request = match[1];
      if (request.startsWith(".")) {
        const resolved = resolveLocalModule(absolutePath, request);
        dependencyMap[request] = normalizePath(resolved);
        visit(resolved);
      } else if (!externalModules[request]) {
        throw new Error(`Unsupported external module ${request} in ${normalizePath(absolutePath)}`);
      }
    }
    moduleMap.set(absolutePath, { id: normalizePath(absolutePath), source, dependencyMap });
  }
  visit(entryFile);
  return Array.from(moduleMap.values()).sort((left, right) => left.id.localeCompare(right.id));
}

function indentSource(source, spaces) {
  const padding = " ".repeat(spaces);
  return source.split("\n").map((line) => `${padding}${line}`).join("\n");
}

function buildBundle(entryPoint) {
  const modules = collectModuleGraph(entryPoint.input);
  const modulesSource = modules.map((record) => [
    `    ${JSON.stringify(record.id)}: function rendererModule(module, exports, require) {`,
    indentSource(record.source, 6),
    "    }"
  ].join("\n")).join(",\n");
  const resolutionSource = modules
    .map((record) => `    ${JSON.stringify(record.id)}: ${JSON.stringify(record.dependencyMap)}`)
    .join(",\n");
  const externalSource = Object.entries(externalModules).map(([name, config]) => [
    `    ${JSON.stringify(name)}: function loadExternalModule(globalObject) {`,
    `      const resolved = globalObject && globalObject[${JSON.stringify(config.globalName)}];`,
    `      if (typeof resolved === 'undefined') throw new Error("External module ${name} is unavailable");`,
    "      return resolved;",
    "    }"
  ].join("\n")).join(",\n");

  return [
    "/* eslint-disable */",
    `// Auto-generated renderer bundle for ${entryPoint.name}.`,
    "// Generated by scripts/build-renderer-bundles.js",
    "(function bootstrapRendererBundle(globalObject) {",
    "  const modules = {",
    modulesSource,
    "  };",
    "  const resolutionMap = {",
    resolutionSource,
    "  };",
    "  const externalLoaders = {",
    externalSource,
    "  };",
    "  const moduleCache = Object.create(null);",
    "  function requireModule(moduleId) {",
    "    if (moduleCache[moduleId]) return moduleCache[moduleId].exports;",
    "    const factory = modules[moduleId];",
    "    if (typeof factory !== 'function') throw new Error(`Unknown bundled module: ${moduleId}`);",
    "    const module = { exports: {} };",
    "    moduleCache[moduleId] = module;",
    "    function localRequire(request) {",
    "      if (externalLoaders[request]) return externalLoaders[request](globalObject);",
    "      const targetModuleId = (resolutionMap[moduleId] || {})[request];",
    "      if (!targetModuleId) throw new Error(`Cannot resolve ${request} from ${moduleId}`);",
    "      return requireModule(targetModuleId);",
    "    }",
    "    factory(module, module.exports, localRequire);",
    "    return module.exports;",
    "  }",
    `  requireModule(${JSON.stringify(normalizePath(entryPoint.input))});`,
    "}(typeof globalThis !== 'undefined' ? globalThis : window));",
    ""
  ].join("\n");
}

fs.mkdirSync(outputDir, { recursive: true });
for (const entryPoint of entryPoints) {
  const outputPath = path.join(outputDir, `${entryPoint.name}.bundle.js`);
  fs.writeFileSync(outputPath, buildBundle(entryPoint), "utf8");
  console.log(`Built ${normalizePath(outputPath)}`);
}
